"""Brute-force solvers for 3-SAT and Vertex Cover, from the definitions."""

from __future__ import annotations

from itertools import combinations, product
from typing import Any


def solve_three_sat(instance: dict[str, Any]) -> bool:
    num_vars = instance["num_vars"]
    clauses = instance["clauses"]
    for assignment in product([False, True], repeat=num_vars):
        # assignment[v-1] is the truth value of variable v.
        ok = True
        for clause in clauses:
            if not any(
                (assignment[abs(lit) - 1] if lit > 0 else not assignment[abs(lit) - 1])
                for lit in clause
            ):
                ok = False
                break
        if ok:
            return True
    return False


def solve_vertex_cover(instance: dict[str, Any]) -> bool:
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k < 0:
        return False
    if k >= n:
        return True
    for size in range(0, k + 1):
        for subset in combinations(range(n), size):
            chosen = set(subset)
            if all(u in chosen or v in chosen for u, v in edges):
                return True
    return False
