"""Brute-force / exact solvers for 3-SAT and Vertex Cover, from the definitions."""

from __future__ import annotations

from itertools import product
from typing import Any


def solve_three_sat(instance: dict[str, Any]) -> bool:
    num_vars = instance["num_vars"]
    clauses = instance["clauses"]
    for assignment in product([False, True], repeat=num_vars):
        ok = True
        for clause in clauses:
            if not any(
                (assignment[abs(lit) - 1] if lit > 0 else not assignment[abs(lit) - 1])
                for lit in clause
            ):
                ok = False
                break
        if ok:
            return True
    return False


def solve_vertex_cover(instance: dict[str, Any]) -> bool:
    """Exact decision procedure via branching on an uncovered edge."""
    edges = [tuple(e) for e in instance["edges"]]
    k = instance["k"]
    if k < 0:
        return False

    def rec(edges, budget):
        if not edges:
            return True
        if budget <= 0:
            return False
        u, v = edges[0]
        # Option 1: include u.
        rest_u = [e for e in edges if e[0] != u and e[1] != u]
        if rec(rest_u, budget - 1):
            return True
        # Option 2: include v.
        rest_v = [e for e in edges if e[0] != v and e[1] != v]
        if rec(rest_v, budget - 1):
            return True
        return False

    return rec(edges, k)
EOF
